  ('53d31b04-8160-54ac-8cc3-fa2e7617b709', '054471b1-6437-5190-89fe-3bd34e5cafdd', 3, 'Dynamics', 'Cambridge International AS & A Level Physics (9702), AS unit 3: Dynamics.', 'published', 3),
  ('70416808-bcb9-5574-a0cb-822efb5c0b58', '054471b1-6437-5190-89fe-3bd34e5cafdd', 4, 'Forces, density and pressure', 'Cambridge International AS & A Level Physics (9702), AS unit 4: Forces, density and pressure.', 'published', 4),
  ('200b4e30-40f2-5647-94ec-444c17e17c0c', '054471b1-6437-5190-89fe-3bd34e5cafdd', 5, 'Work, energy and power', 'Cambridge International AS & A Level Physics (9702), AS unit 5: Work, energy and power.', 'published', 5),
  ('31b542b4-888a-58ec-8714-e0e4a58afa58', '054471b1-6437-5190-89fe-3bd34e5cafdd', 6, 'Deformation of solids', 'Cambridge International AS & A Level Physics (9702), AS unit 6: Deformation of solids.', 'published', 6),
  ('e1abc067-f36b-5705-9142-16ea52c6a432', '054471b1-6437-5190-89fe-3bd34e5cafdd', 7, 'Waves', 'Cambridge International AS & A Level Physics (9702), AS unit 7: Waves.', 'published', 7),
  ('1df1fdb9-ef2a-543b-a3b8-b883824323a7', '054471b1-6437-5190-89fe-3bd34e5cafdd', 8, 'Superposition', 'Cambridge International AS & A Level Physics (9702), AS unit 8: Superposition.', 'published', 8),
  ('a1fe3ce5-57e9-5b67-b5de-0068b08773d4', '054471b1-6437-5190-89fe-3bd34e5cafdd', 9, 'Electricity', 'Cambridge International AS & A Level Physics (9702), AS unit 9: Electricity.', 'published', 9),
  ('efad0ecc-7a4f-58b6-851a-e0c5f236b203', '054471b1-6437-5190-89fe-3bd34e5cafdd', 10, 'D.C. circuits', 'Cambridge International AS & A Level Physics (9702), AS unit 10: D.C. circuits.', 'published', 10),
  ('846f367a-3d75-5af9-9f97-4622577d86a4', '054471b1-6437-5190-89fe-3bd34e5cafdd', 11, 'Particle physics', 'Cambridge International AS & A Level Physics (9702), AS unit 11: Particle physics.', 'published', 11),
  ('68a0e773-5e33-5982-9251-befc479a5b0e', '054471b1-6437-5190-89fe-3bd34e5cafdd', 12, 'Motion in a circle', 'Cambridge International AS & A Level Physics (9702), A Level unit 12: Motion in a circle.', 'published', 12),
  ('ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', '054471b1-6437-5190-89fe-3bd34e5cafdd', 13, 'Gravitational fields', 'Cambridge International AS & A Level Physics (9702), A Level unit 13: Gravitational fields.', 'published', 13),
  ('82d636cf-dde5-596a-a387-51dd35cc746e', '054471b1-6437-5190-89fe-3bd34e5cafdd', 14, 'Temperature', 'Cambridge International AS & A Level Physics (9702), A Level unit 14: Temperature.', 'published', 14),
  ('7de84aed-3f15-548e-a9eb-0f5cd69532ed', '054471b1-6437-5190-89fe-3bd34e5cafdd', 15, 'Ideal gases', 'Cambridge International AS & A Level Physics (9702), A Level unit 15: Ideal gases.', 'published', 15),
  ('9b898437-a755-54cd-b337-0e32203c884a', '054471b1-6437-5190-89fe-3bd34e5cafdd', 16, 'Thermodynamics', 'Cambridge International AS & A Level Physics (9702), A Level unit 16: Thermodynamics.', 'published', 16),
  ('d6d89b52-4102-5125-b889-8553296637fa', '054471b1-6437-5190-89fe-3bd34e5cafdd', 17, 'Oscillations', 'Cambridge International AS & A Level Physics (9702), A Level unit 17: Oscillations.', 'published', 17),
  ('2d439b19-3986-5e82-bf64-03173cdf6093', '054471b1-6437-5190-89fe-3bd34e5cafdd', 18, 'Electric fields', 'Cambridge International AS & A Level Physics (9702), A Level unit 18: Electric fields.', 'published', 18),
  ('892f60c0-e550-5135-ad19-709b031a95cc', '054471b1-6437-5190-89fe-3bd34e5cafdd', 19, 'Capacitance', 'Cambridge International AS & A Level Physics (9702), A Level unit 19: Capacitance.', 'published', 19),
  ('c53fa107-bac9-5f71-8c5e-45b48228a3f5', '054471b1-6437-5190-89fe-3bd34e5cafdd', 20, 'Magnetic fields', 'Cambridge International AS & A Level Physics (9702), A Level unit 20: Magnetic fields.', 'published', 20),
  ('156d5595-b614-5e03-afe6-25dffe62de04', '054471b1-6437-5190-89fe-3bd34e5cafdd', 21, 'Alternating currents', 'Cambridge International AS & A Level Physics (9702), A Level unit 21: Alternating currents.', 'published', 21),
  ('fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', '054471b1-6437-5190-89fe-3bd34e5cafdd', 22, 'Quantum physics', 'Cambridge International AS & A Level Physics (9702), A Level unit 22: Quantum physics.', 'published', 22),
  ('69bcb125-87cd-5ed2-ad5b-eb8e5cc56f29', '054471b1-6437-5190-89fe-3bd34e5cafdd', 23, 'Nuclear physics', 'Cambridge International AS & A Level Physics (9702), A Level unit 23: Nuclear physics.', 'published', 23),
  ('172312cd-7c51-54b4-a517-2cfa51ca5bcd', '054471b1-6437-5190-89fe-3bd34e5cafdd', 24, 'Medical physics', 'Cambridge International AS & A Level Physics (9702), A Level unit 24: Medical physics.', 'published', 24),
  ('e7fad2c7-236e-535e-8d86-ea2cc01fe38f', '054471b1-6437-5190-89fe-3bd34e5cafdd', 25, 'Astronomy and cosmology', 'Cambridge International AS & A Level Physics (9702), A Level unit 25: Astronomy and cosmology.', 'published', 25),
  ('11602933-cd4c-52e3-9193-fcbb1eee010f', '1f9a01dd-71dd-56be-a1aa-2b9f5854bf2b', 1, 'Space, time and motion', 'IB Diploma Programme Physics, theme A: Space, time and motion.', 'published', 1),
  ('7968650b-36db-57a1-9a88-65def69ad39c', '1f9a01dd-71dd-56be-a1aa-2b9f5854bf2b', 2, 'The particulate nature of matter', 'IB Diploma Programme Physics, theme B: The particulate nature of matter.', 'published', 2),
  ('261b9517-31ef-51c0-a384-d78c9776f8ef', '1f9a01dd-71dd-56be-a1aa-2b9f5854bf2b', 5, 'Nuclear and quantum physics', 'IB Diploma Programme Physics, theme E: Nuclear and quantum physics.', 'published', 5)
INSERT INTO topics (id, chapter_id, topic_name, "order", required_tier, curriculum_ids, topic_code, as_topic_code, a_level_topic_code, ib_topic_code, syllabus_reference) VALUES
  ('30eaab79-5b9f-5e56-8a20-88e3aa818738', '4ebec9b8-ca0d-5bac-a847-be4ad8bce51f', 'SI base units and homogeneity', 1, 0, ARRAY['as', 'a-level']::TEXT[], NULL, '1.2', '1.2', NULL, 'Recall the SI base quantities and units, express derived units as products or quotients of base units, and use them to check that an equation is homogeneous.'),
  ('7906d9b2-4dd8-584b-907b-68c9fa9e08e4', '4ebec9b8-ca0d-5bac-a847-be4ad8bce51f', 'Errors and uncertainties', 2, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '1.3', '1.3', 'Tool 3', 'Distinguish systematic from random errors and accuracy from precision; assess and combine absolute, fractional and percentage uncertainties.'),
  ('69f49b38-4492-521c-be78-56effb528ad2', 'c0c1987c-1721-5f72-9c37-822234cac0a9', 'Equations of motion', 1, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '2.1', '2.1', 'A.1', 'Define displacement, velocity and acceleration; use displacement–time and velocity–time graphs; derive and use the equations of uniformly accelerated motion in a straight line.'),
  ('22a42568-867c-5245-91eb-c50c73e0ecb6', 'c0c1987c-1721-5f72-9c37-822234cac0a9', 'Projectile motion', 2, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '2.1', '2.1', 'A.1', 'Solve problems on motion under uniform acceleration in two dimensions by treating the horizontal and vertical motions independently.'),
  ('291b09fb-6132-5b3e-9e36-6e892aedc194', '53d31b04-8160-54ac-8cc3-fa2e7617b709', 'Momentum and Newton''s laws of motion', 1, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '3.1', '3.1', 'A.2', 'Define linear momentum; state Newton’s three laws and use F = Δp/Δt, with F = ma as the special case of constant mass; weight as W = mg.'),
  ('886c3d51-8187-5c06-9624-0a1fdf5374c5', '53d31b04-8160-54ac-8cc3-fa2e7617b709', 'Drag and terminal velocity', 2, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '3.2', '3.2', 'A.2', 'Describe how air resistance and viscous drag increase with speed, and the motion of an object falling in a uniform field with drag, reaching terminal velocity.'),
  ('42c67aa7-36ea-56ea-881a-771edd16371c', '53d31b04-8160-54ac-8cc3-fa2e7617b709', 'Conservation of momentum and collisions', 3, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '3.3', '3.3', 'A.2', 'Apply conservation of momentum to collisions and interactions in one and two dimensions; distinguish elastic from inelastic collisions using relative speeds of approach and separation.'),
  ('39873a63-ead0-5e05-a120-24f13c91d12e', '70416808-bcb9-5574-a0cb-822efb5c0b58', 'Couples and torque', 1, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '4.1', '4.1', 'A.4', 'Define the moment of a force and the torque of a couple, and apply the principle of moments to a system in equilibrium.'),
  ('59eb809b-0e5d-561b-afef-f6562ee5d2f9', '70416808-bcb9-5574-a0cb-822efb5c0b58', 'Equilibrium and the triangle of forces', 2, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '4.2', '4.2', 'A.2', 'Use the conditions for equilibrium — no resultant force and no resultant moment — and represent three coplanar forces in equilibrium with a closed vector triangle.'),
  ('1e63820e-0e97-5246-a289-e87b74bc35b6', '70416808-bcb9-5574-a0cb-822efb5c0b58', 'Upthrust and Archimedes’ principle', 3, 0, ARRAY['as', 'a-level']::TEXT[], NULL, '4.3', '4.3', NULL, 'Define density and pressure; derive Δp = ρgΔh; explain upthrust as the pressure difference across a submerged object, and use F = ρgV.'),
  ('350a9202-2d56-5f66-941e-098871f5a3a5', '200b4e30-40f2-5647-94ec-444c17e17c0c', 'Work, efficiency and power', 1, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '5.1', '5.1', 'A.3', 'Use work done W = Fs cos θ, the conservation of energy and efficiency, and power as the rate of doing work, including P = Fv.'),
  ('2f93eddd-0902-5249-8e7f-b8b8326710fa', '200b4e30-40f2-5647-94ec-444c17e17c0c', 'Gravitational potential energy and kinetic energy', 2, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '5.2', '5.2', 'A.3', 'Derive ΔEₚ = mgΔh and Eₖ = ½mv² from the equations of motion, and use them in energy-conservation problems.'),
  ('6a2f5d2c-1132-5875-af24-b2834a3cbb17', '31b542b4-888a-58ec-8714-e0e4a58afa58', 'Stress, strain and the Young modulus', 1, 0, ARRAY['as', 'a-level']::TEXT[], NULL, '6.1', '6.1', NULL, 'Define and use stress, strain and the Young modulus, and describe an experiment to determine the Young modulus of a metal wire.'),
  ('7ed34d0b-a0bb-5289-923d-2ebe3b09ae33', '31b542b4-888a-58ec-8714-e0e4a58afa58', 'Elastic and plastic behaviour', 2, 0, ARRAY['as', 'a-level']::TEXT[], NULL, '6.2', '6.2', NULL, 'Distinguish elastic from plastic deformation, and find the elastic potential energy from the area under a force–extension graph: E = ½Fx = ½kx².'),
  ('9bb45f5e-00df-54b9-a6b7-5506c9a3ddd7', 'e1abc067-f36b-5705-9142-16ea52c6a432', 'Progressive waves', 1, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '7.1', '7.1', 'C.2', 'Describe progressive waves by displacement, amplitude, phase difference, period, frequency, wavelength and speed; derive v = fλ; intensity ∝ amplitude².'),
  ('786acc15-4120-5802-89d0-87e197dfb6e3', 'e1abc067-f36b-5705-9142-16ea52c6a432', 'Transverse and longitudinal waves', 2, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '7.2', '7.2', 'C.2', 'Compare transverse and longitudinal waves, and analyse graphs of displacement against distance and against time for both.'),
  ('b294efa1-4c2f-54c6-b1cf-502b49e4a3af', 'e1abc067-f36b-5705-9142-16ea52c6a432', 'Doppler effect for sound waves', 3, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '7.3', '7.3', 'C.5', 'Explain the Doppler shift when a source moves relative to a stationary observer, and use fₒ = fₛv/(v ± vₛ).'),
  ('3c3fce3c-4cc1-52c6-82f1-56dfadfcf2a9', 'e1abc067-f36b-5705-9142-16ea52c6a432', 'The electromagnetic spectrum', 4, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '7.4', '7.4', 'C.2', 'Recall that all electromagnetic waves travel at c in free space, and the approximate wavelength range of each principal region of the spectrum.'),
  ('937cf296-0e69-5f58-9b49-31f65bc681c4', 'e1abc067-f36b-5705-9142-16ea52c6a432', 'Polarisation and Malus’s law', 5, 0, ARRAY['as', 'a-level']::TEXT[], NULL, '7.5', '7.5', NULL, 'Understand polarisation as a property of transverse waves only, and use Malus’s law, I = I₀cos²θ.'),
  ('83963be8-be0f-5f96-8364-bde06f064a20', '1df1fdb9-ef2a-543b-a3b8-b883824323a7', 'Stationary waves', 1, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '8.1', '8.1', 'C.4', 'Explain how stationary waves form by superposition, identify nodes and antinodes, and use them to find the wavelength of sound.'),
  ('ac58b38d-7321-565d-b1cd-04b5a99cdbf6', '1df1fdb9-ef2a-543b-a3b8-b883824323a7', 'Diffraction', 2, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '8.2', '8.2', 'C.3', 'Explain diffraction at a gap or an edge, and how the amount of spreading depends on the wavelength compared with the gap width.'),
  ('6838dcd7-1c01-5e62-aebb-22f645fe13bc', '1df1fdb9-ef2a-543b-a3b8-b883824323a7', 'The diffraction grating', 3, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '8.4', '8.4', 'C.3', 'Use d sin θ = nλ for the angles of the maxima from a diffraction grating, and use a grating to measure wavelength.'),
  ('82d3dfd8-e61a-5476-8c20-8663f8268cf4', 'a1fe3ce5-57e9-5b67-b5de-0068b08773d4', 'Electric current and charge carriers', 1, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '9.1', '9.1', 'B.5', 'Understand current as a flow of charge carriers; use Q = It and the quantisation of charge; derive and use I = Anvq.'),
  ('5e3b04c2-03af-5460-93d4-c11d9087c1ab', 'a1fe3ce5-57e9-5b67-b5de-0068b08773d4', 'Potential difference and power', 2, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '9.2', '9.2', 'B.5', 'Define p.d. as energy transferred per unit charge, V = W/Q, and use P = VI, P = I²R and P = V²/R.'),
  ('5a1a1f7e-0787-56ee-8855-7dcd1d3618d5', 'a1fe3ce5-57e9-5b67-b5de-0068b08773d4', 'Resistivity and I–V characteristics', 3, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '9.3', '9.3', 'B.5', 'Sketch the I–V characteristics of a metallic conductor, a filament lamp and a diode; use R = ρL/A; describe how an LDR and a thermistor respond.'),
  ('65252d6c-d56a-5b6e-acf6-220f0f8c3b5c', 'efad0ecc-7a4f-58b6-851a-e0c5f236b203', 'EMF and internal resistance', 1, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '10.1', '10.1', 'B.5', 'Distinguish e.m.f. from p.d. in terms of energy, and explain how internal resistance reduces the terminal p.d.'),
  ('aa1ea4aa-2314-58c6-86d0-391e572ce203', 'efad0ecc-7a4f-58b6-851a-e0c5f236b203', 'Kirchhoff''s laws', 2, 0, ARRAY['as', 'a-level']::TEXT[], NULL, '10.2', '10.2', NULL, 'Apply Kirchhoff’s first law (conservation of charge) and second law (conservation of energy), and derive the combined resistance of resistors in series and in parallel.'),
  ('226d1ed7-1670-5c83-82f9-9f3d214faaa6', 'efad0ecc-7a4f-58b6-851a-e0c5f236b203', 'Potential dividers', 3, 0, ARRAY['as', 'a-level']::TEXT[], NULL, '10.3', '10.3', NULL, 'Use a potential divider, including one containing a thermistor or LDR, and understand the principle of the potentiometer.'),
  ('6c1925e6-a3b1-509b-867c-67604094c0d0', '846f367a-3d75-5af9-9f97-4622577d86a4', 'The nuclear atom and radioactive decay', 1, 0, ARRAY['as', 'a-level', 'ib']::TEXT[], NULL, '11.1', '11.1', 'E.1', 'Infer the nuclear atom from α-particle scattering; use nuclide notation; describe α, β⁻, β⁺ and γ emission, including the continuous β energy spectrum and (anti)neutrinos.'),
  ('3e1bee0b-dce4-58a7-b85c-5d53dd4c667e', '846f367a-3d75-5af9-9f97-4622577d86a4', 'Quarks, hadrons and leptons', 2, 0, ARRAY['as', 'a-level']::TEXT[], NULL, '11.2', '11.2', NULL, 'Describe the quark model — up, down and strange quarks and their charges — baryons and mesons as hadrons, leptons, and the quark changes in β⁻ and β⁺ decay.'),
  ('0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', '68a0e773-5e33-5982-9251-befc479a5b0e', 'Radians and angular speed', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '12.1', 'A.2', 'Define the radian and angular displacement, and use angular speed ω = 2π/T and v = rω.'),
  ('748a497a-deae-518a-a929-236d0930052b', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'Gravitational fields and field lines', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '13.1', 'D.1', 'Understand a gravitational field as a field of force, define gravitational field strength as force per unit mass, and represent fields with field lines.'),
  ('f779851e-a0d7-547b-b5a0-d558fa4769be', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'Field strength of a point mass', 2, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '13.3', 'D.1', 'Derive g = GM/r² from Newton’s law of gravitation, and explain why g is approximately constant close to the Earth’s surface.'),
  ('d22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'Gravitational potential', 3, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '13.4', 'D.1', 'Define gravitational potential as the work done per unit mass bringing a small test mass from infinity; use φ = −GM/r and ΔEₚ = mΔφ.'),
  ('57029f9b-b999-54ce-809e-427abcb1c520', '82d636cf-dde5-596a-a387-51dd35cc746e', 'Thermal equilibrium', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '14.1', 'B.1', 'Understand that thermal energy is transferred from higher to lower temperature, and that regions at the same temperature are in thermal equilibrium.'),
  ('44937e02-ca76-55a2-936f-ebfb890a9d89', '82d636cf-dde5-596a-a387-51dd35cc746e', 'Temperature scales', 2, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '14.2', NULL, 'Understand that the thermodynamic scale does not depend on the property of any substance; convert between kelvin and degrees Celsius; use physical properties in thermometers.'),
  ('ea4a2b5f-fc7b-5e52-84b7-b92896426bdd', '82d636cf-dde5-596a-a387-51dd35cc746e', 'Specific heat capacity and latent heat', 3, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '14.3', 'B.1', 'Define and use specific heat capacity and specific latent heat, and describe experiments to measure them.'),
  ('e1c1c48c-6a14-5ab3-b2eb-36b898c80474', '7de84aed-3f15-548e-a9eb-0f5cd69532ed', 'The mole and the Avogadro constant', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '15.1', 'B.3', 'Understand the amount of substance in moles, and use the Avogadro constant N_A = 6.02 × 10²³ mol⁻¹.'),
  ('2dd6660f-f63e-5078-8c92-9b2c1782553d', '7de84aed-3f15-548e-a9eb-0f5cd69532ed', 'The ideal gas equation', 2, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '15.2', 'B.3', 'Recall and use pV = nRT = NkT for an ideal gas, with the Boltzmann constant k = R/N_A.'),
  ('50c14949-b5ee-5ec0-85da-611fddf81a19', '7de84aed-3f15-548e-a9eb-0f5cd69532ed', 'Kinetic theory of gases', 3, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '15.3', 'B.3', 'State the assumptions of the kinetic theory; derive pV = ⅓Nm⟨c²⟩; relate the mean translational kinetic energy of a molecule to temperature, ½m⟨c²⟩ = 3⁄2 kT.'),
  ('57651263-6bbc-5909-9535-85c599a55166', '9b898437-a755-54cd-b337-0e32203c884a', 'Internal energy', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '16.1', 'B.4', 'Understand internal energy as the sum of the random kinetic and potential energies of the molecules, and relate a rise in temperature to a rise in their kinetic energy.'),
  ('ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', '9b898437-a755-54cd-b337-0e32203c884a', 'The first law of thermodynamics', 2, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '16.2', 'B.4', 'Use ΔU = q + W, with W = −pΔV the work done on a gas, and the sign convention for each term.'),
  ('bdf389d3-533a-55ee-8bbf-e1744095737f', 'd6d89b52-4102-5125-b889-8553296637fa', 'Simple harmonic motion', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '17.1', 'C.1', 'Define SHM by a = −ω²x; use x = x₀ sin ωt and v = ±ω√(x₀² − x²); relate the graphs of displacement, velocity and acceleration.'),
  ('326ce4be-3b28-5d8b-baaf-576fbafaa066', 'd6d89b52-4102-5125-b889-8553296637fa', 'Energy in simple harmonic motion', 2, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '17.2', 'C.1', 'Describe the interchange between kinetic and potential energy during SHM, and use E = ½mω²x₀².'),
  ('c3990679-5498-5443-9eb0-7f7a69c8b3cf', 'd6d89b52-4102-5125-b889-8553296637fa', 'Damped and forced oscillations, resonance', 3, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '17.3', 'C.4', 'Describe light, critical and heavy damping, forced oscillations and resonance, and how damping changes the resonance curve.'),
  ('7ef293ce-52e7-56ce-9b56-5d610fce5bd5', '2d439b19-3986-5e82-bf64-03173cdf6093', 'Electric fields and field lines', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '18.1', 'D.2', 'Understand an electric field as a field of force, define field strength as force per unit positive charge, and represent fields with field lines.'),
  ('ea6e0ded-f55f-54ce-803b-1143224c470a', '2d439b19-3986-5e82-bf64-03173cdf6093', 'Uniform electric fields', 2, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '18.2', 'D.3', 'Use E = ΔV/Δd for the uniform field between parallel plates, and describe the motion of a charged particle entering it.'),
  ('98f6ff7c-f938-51ef-8ee8-ad6d4052a483', '2d439b19-3986-5e82-bf64-03173cdf6093', 'Field strength of a point charge', 3, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '18.4', 'D.2', 'Use E = Q/(4πε₀r²) for the field strength due to a point charge in free space.'),
  ('8bd140d2-aaf1-5218-a708-16b05f8b7b0d', '2d439b19-3986-5e82-bf64-03173cdf6093', 'Electric potential', 4, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '18.5', 'D.2', 'Define electric potential; use V = Q/(4πε₀r), electric potential energy Eₚ = qV, and field strength as the negative potential gradient.'),
  ('98bbfcc1-1e3c-5d99-be0d-e19121542f69', '892f60c0-e550-5135-ad19-709b031a95cc', 'Capacitors and capacitance', 1, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '19.1', NULL, 'Define capacitance, C = Q/V, and derive the combined capacitance of capacitors in series and in parallel.'),
  ('1f2d9fae-c676-5618-9e77-df3b1c100686', '892f60c0-e550-5135-ad19-709b031a95cc', 'Energy stored in a capacitor', 2, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '19.2', NULL, 'Find the energy stored from the area under a p.d.–charge graph, W = ½QV = ½CV².'),
  ('0c42a207-4bd1-5379-b11d-d983544be962', '892f60c0-e550-5135-ad19-709b031a95cc', 'Discharging a capacitor', 3, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '19.3', NULL, 'Analyse the discharge of a capacitor through a resistor: time constant τ = RC and x = x₀e^(−t/RC) for current, charge or p.d.'),
  ('ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'c53fa107-bac9-5f71-8c5e-45b48228a3f5', 'Magnetic fields and flux density', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '20.1', 'D.2', 'Understand a magnetic field as a field of force produced by moving charges or permanent magnets, and represent it with field lines.'),
  ('58c686dd-7b6b-5113-bac6-799f7572dda5', 'c53fa107-bac9-5f71-8c5e-45b48228a3f5', 'Force on a current-carrying conductor', 2, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '20.2', 'D.3', 'Use F = BIL sin θ and Fleming’s left-hand rule, and define magnetic flux density and the tesla.'),
  ('ca14c791-7996-5cb6-9fb9-b8764146fc83', 'c53fa107-bac9-5f71-8c5e-45b48228a3f5', 'Force on a moving charge', 3, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '20.3', 'D.3', 'Use F = BQv sin θ; analyse the circular path of a charged particle in a uniform field, velocity selection and the Hall voltage.'),
  ('97b06d01-998b-5bf4-8645-77d648f0a328', 'c53fa107-bac9-5f71-8c5e-45b48228a3f5', 'Magnetic fields due to currents', 4, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '20.4', 'D.2', 'Sketch the fields of a long straight wire, a flat circular coil and a long solenoid, and explain the forces between current-carrying conductors.'),
  ('2ad404cd-23bd-5405-96a2-9ca0a634169b', 'c53fa107-bac9-5f71-8c5e-45b48228a3f5', 'Electromagnetic induction', 5, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '20.5', 'D.4', 'Define magnetic flux and flux linkage, and use Faraday’s and Lenz’s laws to find the size and direction of an induced e.m.f.'),
  ('521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', '156d5595-b614-5e03-afe6-25dffe62de04', 'Alternating current and r.m.s. values', 1, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '21.1', NULL, 'Describe sinusoidal a.c. by its period, frequency, peak value and r.m.s. value; use I_rms = I₀/√2 and mean power = ½ × peak power for a resistive load.'),
  ('71ba01f7-9a9e-5018-974d-21999c276ce5', '156d5595-b614-5e03-afe6-25dffe62de04', 'Rectification and smoothing', 2, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '21.2', NULL, 'Distinguish half-wave from full-wave rectification with diodes, and explain smoothing by a capacitor.'),
  ('6403e30c-f596-5ad5-a997-b63837482348', 'fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', 'Photons: energy and momentum', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '22.1', 'E.1', 'Understand the particulate nature of electromagnetic radiation: photon energy E = hf, momentum p = E/c, and the electronvolt.'),
  ('7b93970a-92bd-55df-bca6-9d3907e1c231', 'fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', 'The photoelectric effect', 2, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '22.2', 'E.2', 'Explain photoelectric emission using photons, threshold frequency and work function, and use hf = Φ + ½mv²ₘₐₓ.'),
  ('5859af45-f88d-5515-9a6d-031a8e33d756', 'fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', 'Wave–particle duality', 3, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '22.3', 'E.2', 'Describe electron diffraction as evidence for the wave nature of particles, and use the de Broglie wavelength λ = h/p.'),
  ('9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', 'Energy levels and line spectra', 4, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '22.4', 'E.1', 'Explain emission and absorption line spectra using discrete electron energy levels, hf = E₁ − E₂.'),
  ('c7d1948a-561e-56c0-8776-090012819a77', '69bcb125-87cd-5ed2-ad5b-eb8e5cc56f29', 'Mass defect and binding energy', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '23.1', 'E.3', 'Use E = mc², mass defect and binding energy per nucleon, and relate the binding-energy-per-nucleon curve to fission and fusion.'),
  ('c42a4d3d-be78-5670-938b-975bb2eaf1ec', '172312cd-7c51-54b4-a517-2cfa51ca5bcd', 'Ultrasound', 1, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '24.1', NULL, 'Explain how piezoelectric transducers generate and detect ultrasound; use specific acoustic impedance Z = ρc and the intensity reflection coefficient.'),
  ('fed684c4-735b-500a-85f8-bf99a91029e7', '172312cd-7c51-54b4-a517-2cfa51ca5bcd', 'X-ray imaging and CT', 2, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '24.2', NULL, 'Explain the production of X-rays, attenuation I = I₀e^(−μx), image contrast and how CT scanning builds a 3D image.'),
  ('36e936df-9896-57b6-a5e3-651ca3d785ed', '172312cd-7c51-54b4-a517-2cfa51ca5bcd', 'PET scanning', 3, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '24.3', NULL, 'Explain PET scanning: β⁺-emitting tracers, electron–positron annihilation and detection of the two gamma photons.'),
  ('c1dea5ed-8a5a-585f-8f31-604ecae9ba9f', 'e7fad2c7-236e-535e-8d86-ea2cc01fe38f', 'Standard candles and luminosity', 1, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '25.1', 'E.5', 'Understand luminosity and radiant flux intensity, F = L/(4πd²), and how standard candles are used to measure distances.'),
  ('2df83c3e-834f-517a-a55c-cf1ff80eccfb', 'e7fad2c7-236e-535e-8d86-ea2cc01fe38f', 'Stellar radii: Wien and Stefan–Boltzmann', 2, 0, ARRAY['a-level', 'ib']::TEXT[], NULL, NULL, '25.2', 'E.5', 'Use Wien’s displacement law, λₘₐₓ ∝ 1/T, and the Stefan–Boltzmann law, L = 4πσr²T⁴, to estimate the radius of a star.'),
  ('397b2565-7a2c-5e16-a138-021d30b81dd9', 'e7fad2c7-236e-535e-8d86-ea2cc01fe38f', 'Hubble’s law and the Big Bang', 3, 0, ARRAY['a-level']::TEXT[], NULL, NULL, '25.3', NULL, 'Use redshift, Δλ/λ ≈ Δf/f ≈ v/c, and Hubble’s law, v ≈ H₀d, as evidence for an expanding Universe and the Big Bang theory.'),
  ('d9e5187f-66fd-5a6c-9338-c6fbc9c7a4ef', '11602933-cd4c-52e3-9193-fcbb1eee010f', 'Moment of inertia and angular momentum', 1, 0, ARRAY['ib']::TEXT[], NULL, NULL, NULL, 'A.4', 'Describe rotational motion with torque, moment of inertia, angular acceleration and angular momentum: τ = Iα and L = Iω. (HL)'),
  ('d9259e69-4951-5c09-a991-85ce4403a3b5', '11602933-cd4c-52e3-9193-fcbb1eee010f', 'Special relativity', 2, 0, ARRAY['ib']::TEXT[], NULL, NULL, NULL, 'A.5', 'Use Galilean transformations, the postulates of special relativity, Lorentz transformations, time dilation and length contraction. (HL)'),
  ('4e857710-300f-5806-9c1d-82c9a072b01b', '7968650b-36db-57a1-9a88-65def69ad39c', 'The greenhouse effect', 1, 0, ARRAY['ib']::TEXT[], NULL, NULL, NULL, 'B.2', 'Model the Earth’s energy balance using the Stefan–Boltzmann law, emissivity and albedo, and explain the greenhouse effect.'),
  ('317d47ad-db15-513f-8570-63a5237e0e88', '7968650b-36db-57a1-9a88-65def69ad39c', 'Entropy and the second law', 2, 0, ARRAY['ib']::TEXT[], NULL, NULL, NULL, 'B.4', 'Apply the first law to gas processes and heat-engine cycles, and understand entropy, the second law of thermodynamics and Carnot efficiency. (HL)'),
  ('45211a52-245d-50f0-9454-6fff9a385be4', '261b9517-31ef-51c0-a384-d78c9776f8ef', 'Nuclear fission', 1, 0, ARRAY['ib']::TEXT[], NULL, NULL, NULL, 'E.4', 'Describe neutron-induced fission, chain reactions and the parts of a nuclear reactor: moderator, control rods, coolant and shielding.'),
  ('259ac9ff-d04b-5c23-8fb2-eb4bbe439557', '261b9517-31ef-51c0-a384-d78c9776f8ef', 'Fusion and stellar evolution', 2, 0, ARRAY['ib']::TEXT[], NULL, NULL, NULL, 'E.5', 'Explain fusion as the energy source of stars, hydrostatic equilibrium, the Hertzsprung–Russell diagram and the evolution of stars of different masses.')
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f00ffd28-22a8-5f26-a19b-80fd37ab60aa', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.1', '9702 2.1 Equations of motion', 1, 1, 'A car accelerates uniformly from 12 m/s to 30 m/s in 6.0 s. Calculate its acceleration.', 1, 'numeric'::answer_type, '3', 'm/s²', NULL, false, 'a = (v − u)/t = (30 − 12) ÷ 6.0 = 3.0 m/s².', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('04910081-3798-576e-ab9b-6ad7f46d14d3', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.1', '9702 2.1 Equations of motion', 2, 2, 'A train travelling at 25 m/s brakes uniformly and comes to rest in a distance of 400 m. Calculate the magnitude of its deceleration.', 2, 'numeric'::answer_type, '0.7812', 'm/s²', NULL, false, 'Use v² = u² + 2as with v = 0: 0 = 25² + 2a × 400, so a = −625 ÷ 800 = −0.781 m/s². The deceleration is 0.781 m/s².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b707a772-9c5a-54e0-b1e6-a99c56f54df4', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.1', '9702 2.1 Equations of motion', 3, 3, 'A ball is thrown vertically upwards at 18 m/s. Ignoring air resistance, calculate the maximum height it reaches above the point of release. Take g = 9.81 m/s².', 2, 'numeric'::answer_type, '16.51', 'm', NULL, false, 'At the top v = 0. With a = −9.81 m/s²: 0 = 18² − 2 × 9.81 × s, so s = 324 ÷ 19.62 = 16.5 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('59a912ef-ff21-51e6-8934-e9e918d980b2', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.1', '9702 2.1 Equations of motion', 4, 4, 'A stone is dropped from rest from the top of a 45 m cliff. Ignoring air resistance, calculate the time it takes to reach the sea below. Take g = 9.81 m/s².', 2, 'numeric'::answer_type, '3.029', 's', NULL, false, 's = ut + ½at² with u = 0: 45 = ½ × 9.81 × t², so t = √(90 ÷ 9.81) = 3.03 s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('01dfc716-8423-55e9-b867-832642d80633', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.1', '9702 2.1 Equations of motion', 5, 5, 'A cyclist moving at 4.0 m/s accelerates uniformly at 1.5 m/s² for 6.0 s. Calculate her displacement during this time.', 2, 'numeric'::answer_type, '51', 'm', NULL, false, 's = ut + ½at² = 4.0 × 6.0 + ½ × 1.5 × 6.0² = 24 + 27 = 51.0 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('67a91bc1-0942-5528-b17f-939c75d75a84', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.1', '9702 2.1 Equations of motion', 6, 6, 'What does the area under a velocity–time graph represent?', 1, 'multiple_choice'::answer_type, 'Displacement', NULL, NULL, false, 'Area under a v–t graph is velocity × time, which is displacement. The GRADIENT of a v–t graph is the acceleration.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('232928db-7d2f-5799-8ea7-2c94eb33375f', '67a91bc1-0942-5528-b17f-939c75d75a84', 'Displacement', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fa75a345-85d9-554d-bf0e-0760f48615be', '67a91bc1-0942-5528-b17f-939c75d75a84', 'Acceleration', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('566b0ba8-d3d6-5bae-ad6f-0a910d5ae086', '67a91bc1-0942-5528-b17f-939c75d75a84', 'Velocity', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('713bc647-3dd3-578f-909b-68bb308728bf', '67a91bc1-0942-5528-b17f-939c75d75a84', 'Force', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('85e6ac73-5f27-5879-aed0-17f5eb2a7918', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.1', '9702 2.1 Equations of motion (two dimensions)', 1, 1, 'A ball rolls off the edge of a horizontal table 1.25 m high at 3.0 m/s. Ignoring air resistance, calculate how far from the foot of the table it lands. Take g = 9.81 m/s².', 2, 'numeric'::answer_type, '1.514', 'm', NULL, false, 'Vertically the ball starts with zero velocity: 1.25 = ½ × 9.81 × t², so t = 0.505 s. Horizontally the speed stays 3.0 m/s, so x = 3.0 × 0.505 = 1.51 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ba9fea24-b648-55cf-8ab4-092fa5f7ae57', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.1', '9702 2.1 Equations of motion (two dimensions)', 2, 2, 'A projectile is launched from level ground at 20 m/s at 30° above the horizontal. Ignoring air resistance, calculate its time of flight. Take g = 9.81 m/s².', 2, 'numeric'::answer_type, '2.039', 's', NULL, false, 'The vertical component is 20 sin30° = 10 m/s. It lands when the vertical displacement is zero again: t = 2 × 10 ÷ 9.81 = 2.04 s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fc81111c-7be0-5f0a-b424-3b1be78002d6', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.1', '9702 2.1 Equations of motion (two dimensions)', 3, 3, 'The same projectile (20 m/s at 30° above the horizontal, from level ground) lands back on the ground. Calculate its horizontal range. Take g = 9.81 m/s².', 3, 'numeric'::answer_type, '35.31', 'm', NULL, false, 'Horizontal velocity = 20 cos30° = 17.3 m/s, time of flight = 2.04 s, so range = 17.3 × 2.04 = 35.3 m.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f7550348-abc6-5b94-b64e-6a736b0ff0d5', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.1', '9702 2.1 Equations of motion (two dimensions)', 4, 4, 'A football is kicked at 25 m/s at 40° above the horizontal. Ignoring air resistance, calculate the maximum height it reaches. Take g = 9.81 m/s².', 3, 'numeric'::answer_type, '13.16', 'm', NULL, false, 'Only the vertical component matters: u_y = 25 sin40° = 16.1 m/s. At the top v_y = 0, so h = u_y² ÷ 2g = 16.1² ÷ 19.62 = 13.2 m.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9e291f16-ea5b-5a55-b737-6d631a36712a', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.1', '9702 2.1 Equations of motion (two dimensions)', 5, 5, 'A projectile moves through the air with no air resistance. Which statement is true at the highest point of its path?', 1, 'multiple_choice'::answer_type, 'Its acceleration is 9.81 m/s² downwards', NULL, NULL, false, 'Gravity acts throughout the flight, so the acceleration is always g downwards — even at the top. Only the VERTICAL velocity is zero there; the horizontal velocity is unchanged.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ddc206d6-9de8-5b70-a2b4-d7777e92601d', '9e291f16-ea5b-5a55-b737-6d631a36712a', 'Its acceleration is 9.81 m/s² downwards', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('152d6117-58cc-5b94-a55e-c1388987f681', '9e291f16-ea5b-5a55-b737-6d631a36712a', 'Its velocity is zero', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('409cb535-5663-51eb-9254-2a9cce9764e6', '9e291f16-ea5b-5a55-b737-6d631a36712a', 'Its acceleration is zero', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6b6dfdcf-4548-5e8b-9648-0d9a8aa168c8', '9e291f16-ea5b-5a55-b737-6d631a36712a', 'Its horizontal velocity is zero', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f33d39c8-c773-5a84-b416-efea4c9b2798', '4ebec9b8-ca0d-5bac-a847-be4ad8bce51f', '7906d9b2-4dd8-584b-907b-68c9fa9e08e4', 'as', '1.3', '9702 1.3 Errors and uncertainties', 1, 1, 'A length is measured as 25.0 ± 0.1 cm. Calculate the percentage uncertainty in the measurement.', 1, 'numeric'::answer_type, '0.4', '%', NULL, false, 'Percentage uncertainty = (absolute uncertainty ÷ value) × 100 = (0.1 ÷ 25.0) × 100 = 0.4%.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bb656b52-9e06-5a7e-9b4e-b959ac9f5a00', '4ebec9b8-ca0d-5bac-a847-be4ad8bce51f', '7906d9b2-4dd8-584b-907b-68c9fa9e08e4', 'as', '1.3', '9702 1.3 Errors and uncertainties', 2, 2, 'A resistance is found from R = V/I, where V = 6.0 ± 0.1 V and I = 2.0 ± 0.1 A. Calculate the percentage uncertainty in R.', 2, 'numeric'::answer_type, '6.667', '%', NULL, false, 'For a quotient, add the percentage uncertainties: V has (0.1 ÷ 6.0) × 100 = 1.67% and I has (0.1 ÷ 2.0) × 100 = 5.0%, so R has 6.67%.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6d3acfe8-e766-53f2-9291-b3c347500d0b', '4ebec9b8-ca0d-5bac-a847-be4ad8bce51f', '7906d9b2-4dd8-584b-907b-68c9fa9e08e4', 'as', '1.3', '9702 1.3 Errors and uncertainties', 3, 3, 'The side of a cube is measured as 2.00 ± 0.02 cm. Calculate the percentage uncertainty in the volume of the cube.', 2, 'numeric'::answer_type, '3', '%', NULL, false, 'The side has a 1.0% uncertainty. V = l³, and for a power the percentage uncertainty is multiplied by the power: 3 × 1.0% = 3.0%.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5623d65d-ceed-56bf-b48d-30698cf04f4f', '4ebec9b8-ca0d-5bac-a847-be4ad8bce51f', '7906d9b2-4dd8-584b-907b-68c9fa9e08e4', 'as', '1.3', '9702 1.3 Errors and uncertainties', 4, 4, 'Two quantities are measured as A = 5.0 ± 0.2 and B = 3.0 ± 0.1. Calculate the absolute uncertainty in C = A − B.', 2, 'numeric'::answer_type, '0.3', NULL, NULL, false, 'For a sum OR a difference, add the absolute uncertainties: 0.2 + 0.1 = 0.3. (Subtracting never cancels uncertainty.)', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9dc03a54-8dcc-509e-ab56-d9d302ffcadf', '4ebec9b8-ca0d-5bac-a847-be4ad8bce51f', '7906d9b2-4dd8-584b-907b-68c9fa9e08e4', 'as', '1.3', '9702 1.3 Errors and uncertainties', 5, 5, 'A micrometer screw gauge reads 0.02 mm when its jaws are fully closed. What kind of error does this cause in every reading taken with it?', 1, 'multiple_choice'::answer_type, 'A systematic error', NULL, NULL, false, 'A zero error shifts every reading by the same amount in the same direction — that is a systematic error. Repeating readings and averaging reduces random errors only; a systematic error must be corrected by subtracting the zero reading.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('21e81935-55d5-5fa7-85a7-48d3d83f9593', '9dc03a54-8dcc-509e-ab56-d9d302ffcadf', 'A systematic error', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2f36fe11-efe8-58fa-b8aa-3e72e967c64d', '9dc03a54-8dcc-509e-ab56-d9d302ffcadf', 'A random error', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8df4459c-cc76-5e09-bccf-ba83c7d81cc8', '9dc03a54-8dcc-509e-ab56-d9d302ffcadf', 'A parallax error that averages out', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4ede9eed-55ad-5cf2-9178-cadf7c29e7d5', '9dc03a54-8dcc-509e-ab56-d9d302ffcadf', 'No error, if readings are repeated', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4c066b69-f432-578e-97e3-4c5afd2f72d4', '4ebec9b8-ca0d-5bac-a847-be4ad8bce51f', '7906d9b2-4dd8-584b-907b-68c9fa9e08e4', 'as', '1.3', '9702 1.3 Errors and uncertainties', 6, 6, 'A set of repeated readings are all very close to one another, but far from the true value. How are the readings best described?', 1, 'multiple_choice'::answer_type, 'Precise but not accurate', NULL, NULL, false, 'Precision is about how close the readings are to each other (small spread). Accuracy is about how close they are to the true value. Close together but off-target is precise but inaccurate — typical of a systematic error.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a732af03-2801-5d77-be48-77614090d054', '4c066b69-f432-578e-97e3-4c5afd2f72d4', 'Precise but not accurate', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0d01d237-20d9-5ade-922c-c2678b6d2d0c', '4c066b69-f432-578e-97e3-4c5afd2f72d4', 'Accurate but not precise', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cb662803-0ee6-58a5-8a46-6777105a8a92', '4c066b69-f432-578e-97e3-4c5afd2f72d4', 'Both accurate and precise', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3a95ddcd-6866-5da0-b714-3f15715d0848', '4c066b69-f432-578e-97e3-4c5afd2f72d4', 'Neither accurate nor precise', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ae680b5d-b5af-5469-b0f3-b8ea93d1a15a', '31b542b4-888a-58ec-8714-e0e4a58afa58', '6a2f5d2c-1132-5875-af24-b2834a3cbb17', 'as', '6.1', '9702 6.1 Stress and strain', 1, 1, 'A steel wire of diameter 0.50 mm supports a load of 60 N. Calculate the tensile stress in the wire.', 2, 'numeric'::answer_type, '3.056e8', 'Pa', 0.03, false, 'Cross-sectional area A = πr² = π × (0.25 × 10⁻³)² = 1.96 × 10⁻⁷ m². Stress = F/A = 60 ÷ 1.96 × 10⁻⁷ = 3.06 × 10⁸ Pa.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3aab21f0-4617-5b56-a11b-bd52890b72ff', '31b542b4-888a-58ec-8714-e0e4a58afa58', '6a2f5d2c-1132-5875-af24-b2834a3cbb17', 'as', '6.1', '9702 6.1 Stress and strain', 2, 2, 'A wire of original length 2.0 m is stretched by 1.2 mm. Calculate the strain.', 1, 'numeric'::answer_type, '6e-4', NULL, NULL, false, 'Strain = extension ÷ original length = 1.2 × 10⁻³ m ÷ 2.0 m = 6.0 × 10⁻⁴. Strain is a ratio of two lengths, so it has no unit.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c238f000-82f0-5a6b-a131-3724051fe0de', '31b542b4-888a-58ec-8714-e0e4a58afa58', '6a2f5d2c-1132-5875-af24-b2834a3cbb17', 'as', '6.1', '9702 6.1 Stress and strain', 3, 3, 'A wire under a stress of 3.0 × 10⁸ Pa has a strain of 1.5 × 10⁻³. Calculate the Young modulus of the material.', 1, 'numeric'::answer_type, '2e11', 'Pa', NULL, false, 'Young modulus E = stress ÷ strain = 3.0 × 10⁸ ÷ 1.5 × 10⁻³ = 2.0 × 10¹¹ Pa.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('be187aed-68fc-5e55-9df7-d6a3c9f68eda', '31b542b4-888a-58ec-8714-e0e4a58afa58', '6a2f5d2c-1132-5875-af24-b2834a3cbb17', 'as', '6.1', '9702 6.1 Stress and strain', 4, 4, 'A copper wire is 1.5 m long and has a cross-sectional area of 2.0 × 10⁻⁷ m². The Young modulus of copper is 1.2 × 10¹¹ Pa. Calculate the extension when a load of 40 N hangs from it, in mm.', 3, 'numeric'::answer_type, '2.5 mm', 'mm', NULL, false, 'Rearrange E = FL/(Ax): x = FL/(AE) = (40 × 1.5) ÷ (2.0 × 10⁻⁷ × 1.2 × 10¹¹) = 60 ÷ 24 000 = 0.00250 m = 2.50 mm.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ad74bcad-ab05-5784-9b02-6fb01f9e7765', '31b542b4-888a-58ec-8714-e0e4a58afa58', '6a2f5d2c-1132-5875-af24-b2834a3cbb17', 'as', '6.1', '9702 6.1 Stress and strain', 5, 5, 'For a metal wire below its limit of proportionality, the Young modulus is equal to the gradient of which graph?', 1, 'multiple_choice'::answer_type, 'Stress against strain', NULL, NULL, false, 'E = stress ÷ strain, so it is the gradient of a stress (y-axis) against strain (x-axis) graph. The gradient of force against extension is the spring constant k, which depends on the wire’s dimensions — the Young modulus does not.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ea371297-b36a-5153-aa41-f7c5e086f5c2', 'ad74bcad-ab05-5784-9b02-6fb01f9e7765', 'Stress against strain', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('66093762-33db-5665-8d31-52411568ee68', 'ad74bcad-ab05-5784-9b02-6fb01f9e7765', 'Strain against stress', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('956f8b2f-20f9-5e33-87df-8df67a95fe0d', 'ad74bcad-ab05-5784-9b02-6fb01f9e7765', 'Force against extension', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9a9bb595-4f5d-59b1-93c9-49d64ce6b669', 'ad74bcad-ab05-5784-9b02-6fb01f9e7765', 'Extension against force', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c00e1c7e-78e2-5a5c-a77d-8bf79607b71a', 'efad0ecc-7a4f-58b6-851a-e0c5f236b203', 'aa1ea4aa-2314-58c6-86d0-391e572ce203', 'as', '10.2', '9702 10.2 Kirchhoff''s laws', 1, 1, 'Currents of 3.0 A and 1.2 A flow into a junction. Two wires carry current away from it; one carries 2.5 A. Calculate the current in the other.', 1, 'numeric'::answer_type, '1.7', 'A', NULL, false, 'Kirchhoff’s first law: total current in = total current out. 3.0 + 1.2 = 2.5 + I, so I = 1.7 A.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('aeb5ca63-d118-5eeb-8636-9dc20c16f6e5', 'efad0ecc-7a4f-58b6-851a-e0c5f236b203', 'aa1ea4aa-2314-58c6-86d0-391e572ce203', 'as', '10.2', '9702 10.2 Kirchhoff''s laws', 2, 2, 'Calculate the combined resistance of a 6.0 Ω resistor and a 3.0 Ω resistor connected in parallel.', 1, 'numeric'::answer_type, '2', 'Ω', NULL, false, '1/R = 1/6.0 + 1/3.0 = 1/6 + 2/6 = 3/6, so R = 2.0 Ω — less than either resistor alone.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1fec681d-76b2-5007-957e-ac96c913ff37', 'efad0ecc-7a4f-58b6-851a-e0c5f236b203', 'aa1ea4aa-2314-58c6-86d0-391e572ce203', 'as', '10.2', '9702 10.2 Kirchhoff''s laws', 3, 3, 'A 12 V battery of negligible internal resistance is connected to a 4.0 Ω resistor in series with a parallel pair of 6.0 Ω and 12 Ω resistors. Calculate the current from the battery.', 2, 'numeric'::answer_type, '1.5', 'A', NULL, false, 'The parallel pair: 1/R = 1/6 + 1/12 = 3/12, so R = 4.0 Ω. Total resistance = 4.0 + 4.0 = 8.0 Ω. I = V/R = 12 ÷ 8.0 = 1.5 A.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1f1a3d3e-1631-5722-ad68-a63299b12358', 'efad0ecc-7a4f-58b6-851a-e0c5f236b203', 'aa1ea4aa-2314-58c6-86d0-391e572ce203', 'as', '10.2', '9702 10.2 Kirchhoff''s laws', 4, 4, 'In the same circuit (12 V; 4.0 Ω in series with 6.0 Ω and 12 Ω in parallel), calculate the current in the 12 Ω resistor.', 3, 'numeric'::answer_type, '0.5', 'A', NULL, false, 'The battery current is 1.5 A. The p.d. across the parallel pair is 1.5 × 4.0 = 6.0 V (Kirchhoff’s second law: 12 V = 6.0 V across the 4.0 Ω + 6.0 V across the pair). So the 12 Ω resistor carries 6.0 ÷ 12 = 0.50 A.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('51073cbe-5d29-5087-b488-e018e3581615', 'efad0ecc-7a4f-58b6-851a-e0c5f236b203', 'aa1ea4aa-2314-58c6-86d0-391e572ce203', 'as', '10.2', '9702 10.2 Kirchhoff''s laws', 5, 5, 'Kirchhoff''s second law is a consequence of the conservation of which quantity?', 1, 'multiple_choice'::answer_type, 'Energy', NULL, NULL, false, 'Round any closed loop the sum of the e.m.f.s equals the sum of the p.d.s: the energy each coulomb gains from sources equals the energy it transfers to components. The FIRST law (currents at a junction) is conservation of charge.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b396de0d-68a6-507d-8f84-e549a58abe6d', '51073cbe-5d29-5087-b488-e018e3581615', 'Energy', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d938b2fb-8bc9-5530-ae89-998a484c84c9', '51073cbe-5d29-5087-b488-e018e3581615', 'Charge', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bd4318e2-c4ee-50ea-bba2-e598cce0143a', '51073cbe-5d29-5087-b488-e018e3581615', 'Momentum', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('710990b8-3d0a-57e4-a4b0-7962c99dd8af', '51073cbe-5d29-5087-b488-e018e3581615', 'Current', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('192d7387-5507-5e20-9c67-fcbcb8c110b0', 'a1fe3ce5-57e9-5b67-b5de-0068b08773d4', '5a1a1f7e-0787-56ee-8855-7dcd1d3618d5', 'as', '9.3', '9702 9.3 Resistance and resistivity', 1, 1, 'A nichrome wire has resistivity 1.1 × 10⁻⁶ Ω m, length 2.0 m and cross-sectional area 5.0 × 10⁻⁷ m². Calculate its resistance.', 1, 'numeric'::answer_type, '4.4', 'Ω', NULL, false, 'R = ρL/A = (1.1 × 10⁻⁶ × 2.0) ÷ 5.0 × 10⁻⁷ = 4.4 Ω.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('420dd07f-1d34-5241-9156-222609feecb8', 'a1fe3ce5-57e9-5b67-b5de-0068b08773d4', '5a1a1f7e-0787-56ee-8855-7dcd1d3618d5', 'as', '9.3', '9702 9.3 Resistance and resistivity', 2, 2, 'A wire of length 1.5 m and diameter 0.40 mm has a resistance of 0.20 Ω. Calculate the resistivity of the metal, in Ω m.', 3, 'numeric'::answer_type, '1.676e-8', 'Ω m', 0.03, false, 'A = π(d/2)² = π × (0.20 × 10⁻³)² = 1.26 × 10⁻⁷ m². ρ = RA/L = 0.20 × 1.26 × 10⁻⁷ ÷ 1.5 = 1.68 × 10⁻⁸ Ω m — about the value for copper.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a51f22ff-ec1c-56ef-9d20-436801fb8b7f', 'a1fe3ce5-57e9-5b67-b5de-0068b08773d4', '5a1a1f7e-0787-56ee-8855-7dcd1d3618d5', 'as', '9.3', '9702 9.3 Resistance and resistivity', 3, 3, 'A 5.0 m length of wire has a resistance of 8.0 Ω. Calculate the resistance of a 2.0 m length of wire made of the same metal but with twice the diameter.', 3, 'numeric'::answer_type, '0.8', 'Ω', NULL, false, 'R = ρL/A and A ∝ d². The length is × 2.0/5.0 = 0.4; doubling the diameter makes the area × 4. R = 8.0 × 0.4 ÷ 4 = 0.800 Ω.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6ade35cd-e6c1-50b0-ace2-eefabdd0a198', 'a1fe3ce5-57e9-5b67-b5de-0068b08773d4', '5a1a1f7e-0787-56ee-8855-7dcd1d3618d5', 'as', '9.3', '9702 9.3 Resistance and resistivity', 4, 4, 'A metal wire is stretched until its length doubles. Its volume and resistivity stay the same. By what factor does its resistance change?', 3, 'multiple_choice'::answer_type, '× 4', NULL, NULL, false, 'Constant volume means doubling L halves A. R = ρL/A, so R goes × 2 from the length and × 2 again from the halved area: × 4 overall.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cc533909-da0e-5d23-88b1-fc375f2b2999', '6ade35cd-e6c1-50b0-ace2-eefabdd0a198', '× 4', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('92b1f48c-5c71-5788-a602-960ad8a1ff65', '6ade35cd-e6c1-50b0-ace2-eefabdd0a198', '× 2', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b8c639cb-084f-5c32-92d6-3b6f4dd865cb', '6ade35cd-e6c1-50b0-ace2-eefabdd0a198', '× ½', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a35d064e-ef73-5dcc-860e-07ccb4eb9275', '6ade35cd-e6c1-50b0-ace2-eefabdd0a198', 'It stays the same', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3b2531a6-1385-5cad-b144-e93e4c1cd581', 'a1fe3ce5-57e9-5b67-b5de-0068b08773d4', '5a1a1f7e-0787-56ee-8855-7dcd1d3618d5', 'as', '9.3', '9702 9.3 Resistance and resistivity', 5, 5, 'As the p.d. across a filament lamp increases, what happens to its resistance, and why?', 1, 'multiple_choice'::answer_type, 'It increases, because the filament gets hotter', NULL, NULL, false, 'A hotter metal filament has ions vibrating with larger amplitude, so the electrons collide more often and the resistance rises. That is why its I–V graph curves towards the V axis.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4e931c75-c5f7-5b0a-886e-cd9ea51f581b', '3b2531a6-1385-5cad-b144-e93e4c1cd581', 'It increases, because the filament gets hotter', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('50049ef8-dd5d-56a4-93be-50bcb0a0b888', '3b2531a6-1385-5cad-b144-e93e4c1cd581', 'It decreases, because more charge carriers are released', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b6138d90-5753-5995-bdba-2ba3054ef772', '3b2531a6-1385-5cad-b144-e93e4c1cd581', 'It stays constant, because the lamp is ohmic', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('894e6dab-927a-5297-88fa-aa1fc365fea5', '3b2531a6-1385-5cad-b144-e93e4c1cd581', 'It increases, because the filament gets longer', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a7fa1809-ef6c-5281-8e4a-0c61aef22c7f', '1df1fdb9-ef2a-543b-a3b8-b883824323a7', '6838dcd7-1c01-5e62-aebb-22f645fe13bc', 'as', '8.4', '9702 8.4 The diffraction grating', 1, 1, 'Light of wavelength 600 nm falls normally on a diffraction grating with 500 lines per mm. Calculate the angle of the first-order maximum, in degrees.', 2, 'numeric'::answer_type, '17.46', '°', NULL, false, 'd = 1 ÷ 500 mm = 2.00 × 10⁻⁶ m. sinθ = nλ/d = 600 × 10⁻⁹ ÷ 2.00 × 10⁻⁶ = 0.300, so θ = 17.5°.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8031da6e-ab23-5139-9c47-e74413be83ec', '1df1fdb9-ef2a-543b-a3b8-b883824323a7', '6838dcd7-1c01-5e62-aebb-22f645fe13bc', 'as', '8.4', '9702 8.4 The diffraction grating', 2, 2, 'For the same grating (500 lines per mm) and light (600 nm), what is the highest order of maximum that can be observed?', 2, 'numeric'::answer_type, '3', NULL, NULL, false, 'sinθ cannot exceed 1, so n ≤ d/λ = 2.00 × 10⁻⁶ ÷ 600 × 10⁻⁹ = 3.33. The highest whole-number order is 3.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c0b003fe-6992-58e0-9d2d-0703ba1b0fd6', '1df1fdb9-ef2a-543b-a3b8-b883824323a7', '6838dcd7-1c01-5e62-aebb-22f645fe13bc', 'as', '8.4', '9702 8.4 The diffraction grating', 3, 3, 'A grating with 300 lines per mm produces a second-order maximum at 20.0° to the straight-through direction. Calculate the wavelength of the light, in nm.', 2, 'numeric'::answer_type, '570 nm', 'nm', NULL, false, 'd = 1 ÷ 300 mm = 3.33 × 10⁻⁶ m. λ = d sinθ / n = 3.33 × 10⁻⁶ × sin20.0° ÷ 2 = 5.70 × 10⁻⁷ m = 570 nm.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('00de90d1-f52f-5cd9-9f48-a18f472d00f3', '1df1fdb9-ef2a-543b-a3b8-b883824323a7', '6838dcd7-1c01-5e62-aebb-22f645fe13bc', 'as', '8.4', '9702 8.4 The diffraction grating', 4, 4, 'Blue light of wavelength 450 nm passes through a grating with 400 lines per mm. Calculate the angle between the two first-order maxima, one either side of the central maximum, in degrees.', 3, 'numeric'::answer_type, '20.74', '°', NULL, false, 'd = 2.50 × 10⁻⁶ m, sinθ = 450 × 10⁻⁹ ÷ 2.50 × 10⁻⁶ = 0.180, θ = 10.4°. The two first-order maxima are at ±10.4°, so they are 20.7° apart.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('10f0fe92-6cf2-5afa-b9c0-c6eb35e55eda', '1df1fdb9-ef2a-543b-a3b8-b883824323a7', '6838dcd7-1c01-5e62-aebb-22f645fe13bc', 'as', '8.4', '9702 8.4 The diffraction grating', 5, 5, 'A diffraction grating is replaced by one with more lines per millimetre. What happens to the maxima for the same light?', 2, 'multiple_choice'::answer_type, 'They are further apart', NULL, NULL, false, 'More lines per mm means a smaller slit spacing d. From sinθ = nλ/d, a smaller d gives a larger θ for each order — the maxima spread further apart, and FEWER orders fit before sinθ reaches 1.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ca9a6cf9-11eb-58c3-a5fe-4a64adbb7d79', '10f0fe92-6cf2-5afa-b9c0-c6eb35e55eda', 'They are further apart', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6cdf0a82-70d7-527f-b011-ba2d386206ac', '10f0fe92-6cf2-5afa-b9c0-c6eb35e55eda', 'They are closer together', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e8ba5281-f3a9-538d-b5d8-b17affedbf22', '10f0fe92-6cf2-5afa-b9c0-c6eb35e55eda', 'They do not move', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c15c3995-6449-5d33-834f-b1ea13c3ad6b', '10f0fe92-6cf2-5afa-b9c0-c6eb35e55eda', 'More orders become visible', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c7dcd35a-6e51-56f7-97ef-f18cd8110b9d', 'a86aff95-adbc-4634-af1f-528e375e2230', '06290016-2fbe-4ff3-aa7e-75bdee8913ef', 'as', '3.1', '9702 3.1 Momentum and Newton''s laws of motion', 1, 1, 'A 0.15 kg ball hits a wall at 20 m/s and rebounds along the same line at 15 m/s. It is in contact with the wall for 0.050 s. Calculate the average force the wall exerts on the ball.', 3, 'numeric'::answer_type, '105', 'N', NULL, false, 'Taking the rebound direction as positive, Δp = 0.15 × 15 − 0.15 × (−20) = 5.25 kg m/s. F = Δp/Δt = 5.25 ÷ 0.050 = 105 N. (Velocity is a vector: the speeds add, they do not subtract.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d5bf4545-889a-5b91-bb77-86188526e748', 'a86aff95-adbc-4634-af1f-528e375e2230', '06290016-2fbe-4ff3-aa7e-75bdee8913ef', 'as', '3.1', '9702 3.1 Momentum and Newton''s laws of motion', 2, 2, 'A 1200 kg car accelerates uniformly from rest to 24 m/s in 8.0 s. Calculate the resultant force on the car.', 1, 'numeric'::answer_type, '3600', 'N', NULL, false, 'F = Δp/Δt = (1200 × 24 − 0) ÷ 8.0 = 3600 N — the same as F = ma with a = 3.0 m/s², because the mass is constant.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1f4876de-8e62-5694-819e-e889b4089549', 'a86aff95-adbc-4634-af1f-528e375e2230', '06290016-2fbe-4ff3-aa7e-75bdee8913ef', 'as', '3.1', '9702 3.1 Momentum and Newton''s laws of motion', 3, 3, 'Calculate the momentum of a 0.060 kg tennis ball moving at 35 m/s.', 1, 'numeric'::answer_type, '2.1', 'kg m/s', NULL, false, 'p = mv = 0.060 × 35 = 2.1 kg m/s, in the direction of motion.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9b74a173-bec2-5d44-84c2-1032c21230a1', 'a86aff95-adbc-4634-af1f-528e375e2230', '06290016-2fbe-4ff3-aa7e-75bdee8913ef', 'as', '3.1', '9702 3.1 Momentum and Newton''s laws of motion', 4, 4, 'Water leaves a hose at 12 m/s at a rate of 2.5 kg per second and hits a wall, where it stops without splashing back. Calculate the force on the wall.', 2, 'numeric'::answer_type, '30', 'N', NULL, false, 'Each second 2.5 kg of water loses 12 m/s, so the momentum lost per second is 2.5 × 12 = 30 kg m/s. Force = rate of change of momentum = 30 N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('95219477-6c8c-5834-89a2-f2f1ff183a4f', 'a86aff95-adbc-4634-af1f-528e375e2230', '06290016-2fbe-4ff3-aa7e-75bdee8913ef', 'as', '3.1', '9702 3.1 Momentum and Newton''s laws of motion', 5, 5, 'An 800 kg lift accelerates upwards at 1.5 m/s². Calculate the tension in the cable. Take g = 9.81 m/s².', 2, 'numeric'::answer_type, '9048', 'N', NULL, false, 'Resultant force upwards = T − mg = ma, so T = m(g + a) = 800 × (9.81 + 1.5) = 9050 N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3c554096-a637-5515-9d6c-6587758e1155', '2d439b19-3986-5e82-bf64-03173cdf6093', '8bd140d2-aaf1-5218-a708-16b05f8b7b0d', 'a-level', '18.5', '9702 18.5 Electric potential', 1, 1, 'Calculate the electric potential at a distance of 0.20 m from a point charge of +4.0 nC. Take ε₀ = 8.85 × 10⁻¹² F/m.', 2, 'numeric'::answer_type, '179.8', 'V', NULL, false, 'V = Q/(4πε₀r) = 4.0 × 10⁻⁹ ÷ (4π × 8.85 × 10⁻¹² × 0.20) = 180 V.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bba08792-010f-5473-bc5e-56071b2b3c1f', '2d439b19-3986-5e82-bf64-03173cdf6093', '8bd140d2-aaf1-5218-a708-16b05f8b7b0d', 'a-level', '18.5', '9702 18.5 Electric potential', 2, 2, 'Calculate the work done in bringing a +2.0 µC charge from infinity to a point where the electric potential is 350 V.', 1, 'numeric'::answer_type, '7e-4', 'J', NULL, false, 'W = qV = 2.0 × 10⁻⁶ × 350 = 7.0 × 10⁻⁴ J.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('815747f7-b125-5bc9-9994-67bf338e0f95', '2d439b19-3986-5e82-bf64-03173cdf6093', '8bd140d2-aaf1-5218-a708-16b05f8b7b0d', 'a-level', '18.5', '9702 18.5 Electric potential', 3, 3, 'Calculate the electric potential energy of a +3.0 µC charge and a −2.0 µC charge placed 0.050 m apart. Give the sign. Take ε₀ = 8.85 × 10⁻¹² F/m.', 3, 'numeric'::answer_type, '-1.079', 'J', NULL, true, 'Eₚ = Q₁Q₂/(4πε₀r) = (3.0 × 10⁻⁶ × −2.0 × 10⁻⁶) ÷ (4π × 8.85 × 10⁻¹² × 0.050) = −1.08 J. It is negative because the charges attract: work must be done to separate them.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fe79a869-016f-57de-bd31-81c69bb3e85f', '2d439b19-3986-5e82-bf64-03173cdf6093', '8bd140d2-aaf1-5218-a708-16b05f8b7b0d', 'a-level', '18.5', '9702 18.5 Electric potential', 4, 4, 'An electron, initially at rest, is accelerated through a potential difference of 2000 V. Calculate its final speed. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', 3, 'numeric'::answer_type, '2.651e7', 'm/s', NULL, false, 'The energy gained is eV = ½mv², so v = √(2eV/m) = √(2 × 1.60 × 10⁻¹⁹ × 2000 ÷ 9.11 × 10⁻³¹) = 2.65 × 10⁷ m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d104ab46-6a32-50b2-bdda-1c206e2870a0', '2d439b19-3986-5e82-bf64-03173cdf6093', '8bd140d2-aaf1-5218-a708-16b05f8b7b0d', 'a-level', '18.5', '9702 18.5 Electric potential', 5, 5, 'How is the electric field strength at a point related to the electric potential there?', 2, 'multiple_choice'::answer_type, 'It is the negative of the potential gradient', NULL, NULL, false, 'E = −ΔV/Δx: the field points in the direction in which the potential falls fastest, and its size is how steeply it falls.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7c514dfc-013b-5613-919d-83e7031016d0', 'd104ab46-6a32-50b2-bdda-1c206e2870a0', 'It is the negative of the potential gradient', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e8423859-19e2-5884-b940-17c1655f8421', 'd104ab46-6a32-50b2-bdda-1c206e2870a0', 'It is equal to the potential', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('105e88c2-f832-546c-8238-03eefca73d70', 'd104ab46-6a32-50b2-bdda-1c206e2870a0', 'It is the potential divided by the charge', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bcd8e623-31a1-5ca1-88f5-3f175139fd4a', 'd104ab46-6a32-50b2-bdda-1c206e2870a0', 'It is the area under a potential–distance graph', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e6f39b6b-35c7-5047-b7bf-2bfa51b44919', '892f60c0-e550-5135-ad19-709b031a95cc', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '19.3', '9702 19.3 Discharging a capacitor', 1, 1, 'Calculate the time constant of a 470 µF capacitor discharging through a 22 kΩ resistor.', 1, 'numeric'::answer_type, '10.34', 's', NULL, false, 'τ = RC = 22 × 10³ × 470 × 10⁻⁶ = 10.3 s.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('33ddc62e-d9c7-504c-b4c5-1b3fe8911a86', '892f60c0-e550-5135-ad19-709b031a95cc', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '19.3', '9702 19.3 Discharging a capacitor', 2, 2, 'A 100 µF capacitor is charged to 12 V and then discharged through a 50 kΩ resistor. Calculate the p.d. across it 8.0 s later.', 2, 'numeric'::answer_type, '2.423', 'V', NULL, false, 'τ = RC = 50 × 10³ × 100 × 10⁻⁶ = 5.0 s. V = V₀e^(−t/RC) = 12 × e^(−8.0/5.0) = 12 × 0.2019 = 2.42 V.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('09863810-b866-55e9-9ef4-6a548e7fb9e6', '892f60c0-e550-5135-ad19-709b031a95cc', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '19.3', '9702 19.3 Discharging a capacitor', 3, 3, 'A 220 µF capacitor discharges through a 10 kΩ resistor. Calculate the time for its charge to fall to half its initial value.', 3, 'numeric'::answer_type, '1.525', 's', NULL, false, 'τ = RC = 2.2 s. Setting Q = ½Q₀ in Q = Q₀e^(−t/RC) gives t = RC ln2 = 2.2 × 0.693 = 1.52 s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c091ec4d-7c63-55f9-ac5e-cf5431ad8d2e', '892f60c0-e550-5135-ad19-709b031a95cc', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '19.3', '9702 19.3 Discharging a capacitor', 4, 4, 'A capacitor charged to 9.0 V starts to discharge through a 4.7 kΩ resistor. Calculate the initial discharge current, in mA.', 1, 'numeric'::answer_type, '1.915 mA', 'mA', NULL, false, 'At the start the full 9.0 V is across the resistor: I₀ = V₀/R = 9.0 ÷ 4700 = 0.00191 A = 1.91 mA. The capacitance only affects how fast the current then falls.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('05e51c65-e7e9-53ac-9545-17ed65104c11', '892f60c0-e550-5135-ad19-709b031a95cc', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '19.3', '9702 19.3 Discharging a capacitor', 5, 5, 'After one time constant, approximately what fraction of its initial charge remains on a discharging capacitor?', 1, 'multiple_choice'::answer_type, '37%', NULL, NULL, false, 'Q = Q₀e^(−t/RC); at t = RC, Q = Q₀e⁻¹ = 0.37Q₀. (63% is the fraction LOST — or the fraction gained when charging.)', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fdee4fbf-40df-58a5-b905-77648a46560b', '05e51c65-e7e9-53ac-9545-17ed65104c11', '37%', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('520982ca-d59f-51b9-8fae-17ead01403d9', '05e51c65-e7e9-53ac-9545-17ed65104c11', '50%', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5bc72036-7923-59fd-8909-35cecc9c5041', '05e51c65-e7e9-53ac-9545-17ed65104c11', '63%', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3b984c8f-1265-5fee-a31c-fc8335225d0b', '05e51c65-e7e9-53ac-9545-17ed65104c11', '10%', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('94fc91b4-b14e-593e-b903-fa4b9667d3c4', 'd6d89b52-4102-5125-b889-8553296637fa', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '17.1', '9702 17.1 Simple harmonic oscillations', 1, 1, 'A mass on a spring oscillates with simple harmonic motion of period 0.50 s and amplitude 3.0 cm. Calculate its maximum acceleration.', 2, 'numeric'::answer_type, '4.737', 'm/s²', NULL, false, 'ω = 2π/T = 2π ÷ 0.50 = 12.6 rad/s. The acceleration is largest at the extremes: a = ω²x₀ = 12.6² × 0.030 = 4.74 m/s².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('25b55678-626a-59dc-b12f-643689c4e35f', 'd6d89b52-4102-5125-b889-8553296637fa', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '17.1', '9702 17.1 Simple harmonic oscillations', 2, 2, 'For the same oscillator (period 0.50 s, amplitude 3.0 cm), calculate the maximum speed of the mass.', 2, 'numeric'::answer_type, '0.377', 'm/s', NULL, false, 'v_max = ωx₀ = 12.6 × 0.030 = 0.377 m/s, reached as the mass passes through the equilibrium position.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a2016012-6b9d-5af4-a7fc-c026b1adf8af', 'd6d89b52-4102-5125-b889-8553296637fa', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '17.1', '9702 17.1 Simple harmonic oscillations', 3, 3, 'For the same oscillator (period 0.50 s, amplitude 3.0 cm), calculate the speed of the mass when it is 1.5 cm from the equilibrium position.', 3, 'numeric'::answer_type, '0.3265', 'm/s', NULL, false, 'v = ω√(x₀² − x²) = 12.6 × √(0.030² − 0.015²) = 12.6 × 0.0260 = 0.326 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('82ed34dc-622b-50e8-bca3-8aeb1ee267d9', 'd6d89b52-4102-5125-b889-8553296637fa', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '17.1', '9702 17.1 Simple harmonic oscillations', 4, 4, 'The acceleration of an oscillating body is given by a = −64x, in SI units. Calculate its frequency.', 2, 'numeric'::answer_type, '1.273', 'Hz', NULL, false, 'Compare with a = −ω²x: ω² = 64, so ω = 8.0 rad/s and f = ω/2π = 8.0 ÷ 2π = 1.27 Hz.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ad1c5e2c-2e66-5e8b-9c99-36fa011ceb39', 'd6d89b52-4102-5125-b889-8553296637fa', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '17.1', '9702 17.1 Simple harmonic oscillations', 5, 5, 'Where in its motion is the acceleration of a body in simple harmonic motion greatest?', 1, 'multiple_choice'::answer_type, 'At maximum displacement', NULL, NULL, false, 'a = −ω²x, so the acceleration is proportional to the displacement: largest at the extremes (where the speed is zero) and zero at the centre (where the speed is greatest).', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c36fd909-86dc-5212-ac8d-cfc8ecd9ae05', 'ad1c5e2c-2e66-5e8b-9c99-36fa011ceb39', 'At maximum displacement', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f3af620d-9c3c-54d5-aff6-52f2fc8f2c91', 'ad1c5e2c-2e66-5e8b-9c99-36fa011ceb39', 'At the equilibrium position', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('648bbccd-f76d-56f6-89a0-f29c91f3802d', 'ad1c5e2c-2e66-5e8b-9c99-36fa011ceb39', 'Halfway between the two', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bbba936a-9668-5765-af61-1346012fc208', 'ad1c5e2c-2e66-5e8b-9c99-36fa011ceb39', 'It is the same everywhere', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('548ca299-c322-5277-b963-0a5d9b948732', 'fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '22.2', '9702 22.2 Photoelectric effect', 1, 1, 'Calculate the energy of a photon of blue light of wavelength 450 nm, in electronvolts. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m/s and e = 1.60 × 10⁻¹⁹ C.', 2, 'numeric'::answer_type, '2.763', 'eV', NULL, false, 'E = hc/λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 450 × 10⁻⁹ = 4.42 × 10⁻¹⁹ J. Dividing by 1.60 × 10⁻¹⁹ J/eV gives 2.76 eV.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('071c3f11-4454-58e6-a6bc-e60481b229ce', 'fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '22.2', '9702 22.2 Photoelectric effect', 2, 2, 'A metal has a work function of 2.3 eV. Calculate its threshold frequency. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m/s and e = 1.60 × 10⁻¹⁹ C.', 2, 'numeric'::answer_type, '5.551e14', 'Hz', NULL, false, 'At threshold the photon energy just equals the work function: hf₀ = Φ, so f₀ = (2.3 × 1.60 × 10⁻¹⁹) ÷ 6.63 × 10⁻³⁴ = 5.55 × 10¹⁴ Hz.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f141106e-7b61-59af-ba03-db8960b128ff', 'fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '22.2', '9702 22.2 Photoelectric effect', 3, 3, 'Ultraviolet light of wavelength 250 nm falls on a metal with work function 4.5 eV. Calculate the maximum kinetic energy of the emitted electrons, in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m/s and e = 1.60 × 10⁻¹⁹ C.', 3, 'numeric'::answer_type, '0.4725', 'eV', 0.05, false, 'Photon energy = hc/λ = 7.96 × 10⁻¹⁹ J = 4.97 eV. Maximum kinetic energy = hf − Φ = 4.97 − 4.5 = 0.473 eV.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('79b439a4-3885-5761-8a4c-6a453ddaf1e8', 'fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '22.2', '9702 22.2 Photoelectric effect', 4, 4, 'Light of frequency 7.5 × 10¹⁴ Hz falls on a surface with work function 2.0 eV. Calculate the stopping potential. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m/s and e = 1.60 × 10⁻¹⁹ C.', 3, 'numeric'::answer_type, '1.108', 'V', 0.05, false, 'hf = 6.63 × 10⁻³⁴ × 7.5 × 10¹⁴ = 4.97 × 10⁻¹⁹ J = 3.11 eV. The fastest electrons have 1.11 eV, so a stopping potential of 1.11 V stops them.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7224ff6e-b47a-5ef1-ba3a-240cfb142263', 'fe5ac8e7-59ec-5c8d-adc4-5e9e1f123332', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '22.2', '9702 22.2 Photoelectric effect', 5, 5, 'The intensity of light shining on a metal is doubled, keeping its frequency the same and above the threshold. What changes?', 2, 'multiple_choice'::answer_type, 'The number of electrons emitted per second', NULL, NULL, false, 'Doubling the intensity doubles the number of photons arriving per second, so twice as many electrons are released each second. Each photon still has energy hf, so the maximum kinetic energy hf − Φ is unchanged — the key evidence for photons.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('66aa42e7-468c-5924-a251-103f1c4cd2bc', '7224ff6e-b47a-5ef1-ba3a-240cfb142263', 'The number of electrons emitted per second', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c29cddbb-b0a1-504f-82f4-a06b67a339fb', '7224ff6e-b47a-5ef1-ba3a-240cfb142263', 'The maximum kinetic energy of the electrons', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('98fcf72a-2ba6-5e6b-81d7-fc493647f526', '7224ff6e-b47a-5ef1-ba3a-240cfb142263', 'The threshold frequency', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('acb5cb0b-fd0a-56b3-8600-cadd22d18492', '7224ff6e-b47a-5ef1-ba3a-240cfb142263', 'The work function', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9c363396-5552-596a-93c1-e7328e440f12', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '23.2', '9702 23.2 Radioactive decay', 1, 1, 'An isotope has a half-life of 1.2 × 10⁴ s. Calculate its decay constant.', 1, 'numeric'::answer_type, '5.776e-5', 's⁻¹', NULL, false, 'λ = ln2 / t½ = 0.693 ÷ 1.2 × 10⁴ = 5.78 × 10⁻⁵ s⁻¹.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ac8e16f6-725f-5413-842e-5833d3df219b', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '23.2', '9702 23.2 Radioactive decay', 2, 2, 'A sample contains 4.0 × 10¹⁸ undecayed nuclei of an isotope with decay constant 2.0 × 10⁻⁶ s⁻¹. Calculate its activity.', 1, 'numeric'::answer_type, '8e12', 'Bq', NULL, false, 'A = λN = 2.0 × 10⁻⁶ × 4.0 × 10¹⁸ = 8.0 × 10¹² Bq.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5f49acd6-07c1-5986-b812-cebb23e88f2f', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '23.2', '9702 23.2 Radioactive decay', 3, 3, 'What fraction of the original nuclei in a sample remains undecayed after 3.5 half-lives? Give your answer as a decimal.', 2, 'numeric'::answer_type, '0.08839', NULL, NULL, false, 'N/N₀ = (½)^3.5 = 0.0884. Equivalently e^(−λt) with λt = 3.5 ln2.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('433377da-3d4a-563e-ac0b-6a0d0c93d004', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '23.2', '9702 23.2 Radioactive decay', 4, 4, 'A sample has an activity of 800 Bq. Its half-life is 6.0 hours. Calculate its activity 15 hours later.', 2, 'numeric'::answer_type, '141.4', 'Bq', NULL, false, '15 h is 15 ÷ 6.0 = 2.5 half-lives, so A = 800 × (½)^2.5 = 800 × 0.1768 = 141 Bq. (A = A₀e^(−λt) gives the same answer.)', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('12a82b4f-fc7e-5d4c-8763-b9e366739929', 'b6a4f484-3024-480c-acfe-3be0a11b5d17', '97e38b4a-35e0-45e7-a53f-405ee0ee00fd', 'a-level', '23.2', '9702 23.2 Radioactive decay', 5, 5, 'The activity of a sample falls from 1200 Bq to 150 Bq. The half-life is 8.0 days. How many days does this take?', 1, 'numeric'::answer_type, '24', 'days', NULL, false, '1200 → 600 → 300 → 150 is three halvings, so the time is 3 × 8.0 = 24 days.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0619129d-6c94-5914-91fd-143e79adbb9b', '157573de-e4fd-418b-9e2b-b4772e5fe137', '523b4920-0883-4788-9903-20af1cf97b2e', 'igcse', '1.2', '0625 1.2 Motion', 1, 1, 'A runner completes one lap of a 400 m track in 50 s. Calculate her average speed.', 1, 'numeric'::answer_type, '8', 'm/s', NULL, false, 'Average speed = total distance ÷ total time = 400 ÷ 50 = 8.0 m/s.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3945aa4a-4b4f-5a0d-8dce-c62653b2c79d', '157573de-e4fd-418b-9e2b-b4772e5fe137', '523b4920-0883-4788-9903-20af1cf97b2e', 'igcse', '1.2', '0625 1.2 Motion', 2, 2, 'A car speeds up from 5.0 m/s to 25 m/s in 4.0 s. Calculate its acceleration.', 1, 'numeric'::answer_type, '5', 'm/s²', NULL, false, 'a = change in velocity ÷ time = (25 − 5.0) ÷ 4.0 = 5.0 m/s².', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8dfa565b-24b0-5809-9e04-981fba9bd30c', '157573de-e4fd-418b-9e2b-b4772e5fe137', '523b4920-0883-4788-9903-20af1cf97b2e', 'igcse', '1.2', '0625 1.2 Motion', 3, 3, 'A train travels at a steady 30 m/s for 2.5 minutes. How far does it travel?', 2, 'numeric'::answer_type, '4500', 'm', NULL, false, 'Convert the time to seconds first: 2.5 minutes = 150 s. Distance = speed × time = 30 × 150 = 4500 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('231ff0c3-f996-5e0f-abf3-05ba239c198d', '157573de-e4fd-418b-9e2b-b4772e5fe137', '523b4920-0883-4788-9903-20af1cf97b2e', 'igcse', '1.2', '0625 1.2 Motion', 4, 4, 'A bus slows down steadily from 18 m/s to rest in 6.0 s. Calculate its deceleration.', 1, 'numeric'::answer_type, '3', 'm/s²', NULL, false, 'a = (0 − 18) ÷ 6.0 = −3.0 m/s². The negative sign means it is slowing down: a deceleration of 3.0 m/s².', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('53015531-12dd-57fa-a19c-58d7eb7a39ab', '157573de-e4fd-418b-9e2b-b4772e5fe137', '523b4920-0883-4788-9903-20af1cf97b2e', 'igcse', '1.2', '0625 1.2 Motion', 5, 5, 'An object accelerates steadily from rest to 12 m/s in 8.0 s. Using its speed–time graph, calculate how far it travels in this time.', 2, 'numeric'::answer_type, '48', 'm', NULL, false, 'Distance = area under the speed–time graph. The graph is a triangle: ½ × base × height = ½ × 8.0 × 12 = 48 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b14f389b-de70-52c8-bfe4-acde0b00ddf2', '0484b128-3d2d-41b8-bab6-74ac48e74dae', '5b81d645-5ec7-4f85-ae6c-4a2c3006142c', 'igcse', '1.4', '0625 1.4 Density', 1, 1, 'A metal block has a mass of 2.0 kg and a volume of 2.5 × 10⁻⁴ m³. Calculate its density.', 1, 'numeric'::answer_type, '8000', 'kg/m³', NULL, false, 'ρ = m/V = 2.0 ÷ 2.5 × 10⁻⁴ = 8000 kg/m³.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('613c0b25-3867-59e6-aea7-1e6f53efbb68', '0484b128-3d2d-41b8-bab6-74ac48e74dae', '5b81d645-5ec7-4f85-ae6c-4a2c3006142c', 'igcse', '1.4', '0625 1.4 Density', 2, 2, 'A stone of mass 66 g is lowered into a measuring cylinder, and the water level rises from 50 cm³ to 72 cm³. Calculate the density of the stone, in g/cm³.', 2, 'numeric'::answer_type, '3', 'g/cm³', NULL, false, 'The stone’s volume is the volume of water it displaces: 72 − 50 = 22 cm³. ρ = m/V = 66 ÷ 22 = 3.0 g/cm³.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('534d831f-7e42-551b-ba62-0a911a50d271', '0484b128-3d2d-41b8-bab6-74ac48e74dae', '5b81d645-5ec7-4f85-ae6c-4a2c3006142c', 'igcse', '1.4', '0625 1.4 Density', 3, 3, 'Oil has a density of 920 kg/m³. Calculate the mass of 0.030 m³ of oil.', 1, 'numeric'::answer_type, '27.6', 'kg', NULL, false, 'm = ρV = 920 × 0.030 = 27.6 kg.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('47be93d8-0faf-537a-b45e-d2d1de7d0936', '0484b128-3d2d-41b8-bab6-74ac48e74dae', '5b81d645-5ec7-4f85-ae6c-4a2c3006142c', 'igcse', '1.4', '0625 1.4 Density', 4, 4, 'A block of aluminium measures 5.0 cm × 4.0 cm × 2.0 cm. The density of aluminium is 2.7 g/cm³. Calculate its mass, in kg.', 2, 'numeric'::answer_type, '0.108', 'kg', NULL, false, 'Volume = 5.0 × 4.0 × 2.0 = 40 cm³. m = ρV = 2.7 × 40 = 108 g = 0.108 kg.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bb0bf6f0-b8ea-56d6-97f5-ef58624a493c', '0484b128-3d2d-41b8-bab6-74ac48e74dae', '5b81d645-5ec7-4f85-ae6c-4a2c3006142c', 'igcse', '1.4', '0625 1.4 Density', 5, 5, 'An object will float in water if its density is…', 1, 'multiple_choice'::answer_type, 'less than the density of water', NULL, NULL, false, 'Objects less dense than the liquid float in it; denser objects sink. Water’s density is 1000 kg/m³ (1.0 g/cm³).', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('af428030-dd4a-5e26-81d0-84ad7b0ae2be', 'bb0bf6f0-b8ea-56d6-97f5-ef58624a493c', 'less than the density of water', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('778d97a3-79ca-53c7-b093-56624fa1d765', 'bb0bf6f0-b8ea-56d6-97f5-ef58624a493c', 'greater than the density of water', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f7472827-3315-5ad2-a4c9-cb79cfb63f72', 'bb0bf6f0-b8ea-56d6-97f5-ef58624a493c', 'equal to its mass', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9e926cbb-d3a0-5543-9e36-920820da637f', 'bb0bf6f0-b8ea-56d6-97f5-ef58624a493c', 'greater than 1 kg/m³', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('30bc7fb1-2882-55b7-87a8-07603ba14fbf', '7968650b-36db-57a1-9a88-65def69ad39c', '4e857710-300f-5806-9c1d-82c9a072b01b', 'ib', 'B.2', 'IB B.2 Greenhouse effect', 1, 1, 'Calculate the power radiated per square metre by a black body at 288 K. Take σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴.', 1, 'numeric'::answer_type, '390.1', 'W/m²', NULL, false, 'Stefan–Boltzmann: P/A = σT⁴ = 5.67 × 10⁻⁸ × 288⁴ = 390 W/m².', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4e5951cd-34df-53c4-92ac-cf91de8afce4', '7968650b-36db-57a1-9a88-65def69ad39c', '4e857710-300f-5806-9c1d-82c9a072b01b', 'ib', 'B.2', 'IB B.2 Greenhouse effect', 2, 2, 'The solar constant is 1360 W/m² and the Earth’s albedo is 0.30. Averaged over the whole surface of the Earth, calculate the power absorbed per square metre.', 2, 'numeric'::answer_type, '238', 'W/m²', NULL, false, 'The Earth intercepts sunlight over a disc of area πR² but spreads it over a sphere of 4πR², so divide by 4; then 30% is reflected. (1 − 0.30) × 1360 ÷ 4 = 238 W/m².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6c56b10d-113f-57c2-9696-01fcb791433a', '7968650b-36db-57a1-9a88-65def69ad39c', '4e857710-300f-5806-9c1d-82c9a072b01b', 'ib', 'B.2', 'IB B.2 Greenhouse effect', 3, 3, 'Using an absorbed intensity of 238 W/m², calculate the equilibrium temperature of an Earth with no atmosphere (emissivity 1). Take σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴.', 3, 'numeric'::answer_type, '254.5', 'K', NULL, false, 'In equilibrium the power emitted equals the power absorbed: σT⁴ = 238, so T = (238 ÷ 5.67 × 10⁻⁸)^¼ = 255 K — about −18 °C, far colder than the real average of 288 K. The difference is the greenhouse effect.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('aceebb05-eaaa-539f-b383-ab94c2bc119d', '7968650b-36db-57a1-9a88-65def69ad39c', '4e857710-300f-5806-9c1d-82c9a072b01b', 'ib', 'B.2', 'IB B.2 Greenhouse effect', 4, 4, 'The Earth’s surface is at 288 K and, with its atmosphere, has an effective emissivity of 0.61. Calculate the power per square metre radiated into space. Take σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴.', 2, 'numeric'::answer_type, '237.9', 'W/m²', NULL, false, 'P/A = eσT⁴ = 0.61 × 5.67 × 10⁻⁸ × 288⁴ = 238 W/m² — matching the power absorbed, so the temperature is steady.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('632e407e-a555-5c03-9a76-7d7aed8c594f', '7968650b-36db-57a1-9a88-65def69ad39c', '4e857710-300f-5806-9c1d-82c9a072b01b', 'ib', 'B.2', 'IB B.2 Greenhouse effect', 5, 5, 'Greenhouse gases such as carbon dioxide warm the Earth mainly because they…', 1, 'multiple_choice'::answer_type, 'absorb infrared radiation emitted by the Earth’s surface', NULL, NULL, false, 'The atmosphere is largely transparent to incoming visible light but greenhouse gas molecules absorb the longer-wavelength infrared the warm surface emits, and re-radiate some of it back down.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8a2be4b7-ebb9-54df-8465-adb92dfddafa', '632e407e-a555-5c03-9a76-7d7aed8c594f', 'absorb infrared radiation emitted by the Earth’s surface', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('431a530e-050a-566f-bd81-ae2dac21e25f', '632e407e-a555-5c03-9a76-7d7aed8c594f', 'absorb visible light arriving from the Sun', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('87b606be-2ac1-55ef-aaed-744c64a066a6', '632e407e-a555-5c03-9a76-7d7aed8c594f', 'reflect sunlight back into space', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e7aa1f53-ced4-5e66-9e05-21b5358488b4', '632e407e-a555-5c03-9a76-7d7aed8c594f', 'increase the Earth’s albedo', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e90c44e3-a1b2-5f9c-8c77-447494570a8c', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'ib', 'A.1', 'IB A.1 Kinematics', 1, 1, 'A car travelling at 22 m/s brakes with a constant deceleration of 5.5 m/s². Calculate its braking distance.', 1, 'numeric'::answer_type, '44', 'm', NULL, false, 'v² = u² + 2as with v = 0: s = u²/2a = 22² ÷ (2 × 5.5) = 44 m.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3b8385bb-5d8d-56d7-9fdf-fb20c58e49be', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'ib', 'A.1', 'IB A.1 Kinematics', 2, 2, 'A ball is dropped from rest from a height of 20 m. Ignoring air resistance, calculate its speed just before it hits the ground. Take g = 9.81 m/s².', 1, 'numeric'::answer_type, '19.81', 'm/s', NULL, false, 'v² = u² + 2as = 0 + 2 × 9.81 × 20 = 392, so v = 19.8 m/s.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ae2340bb-814e-5a5f-b63f-90c719d78891', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'ib', 'A.1', 'IB A.1 Kinematics', 3, 3, 'A ball is thrown vertically upwards at 15 m/s. Ignoring air resistance, how long is it before it returns to the thrower’s hand? Take g = 9.81 m/s².', 2, 'numeric'::answer_type, '3.058', 's', NULL, false, 'It takes 15 ÷ 9.81 = 1.53 s to stop at the top, and the same time to fall back: total 3.06 s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('17f8b695-a2c6-5736-9659-522df3d359a1', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'ib', 'A.1', 'IB A.1 Kinematics', 4, 4, 'A driver travelling at 25 m/s sees a hazard. Her reaction time is 0.80 s, then the car decelerates at 6.0 m/s². Calculate the total stopping distance.', 3, 'numeric'::answer_type, '72.08', 'm', NULL, false, 'Thinking distance = 25 × 0.80 = 20 m at constant speed. Braking distance = u²/2a = 625 ÷ 12 = 52.1 m. Total = 72.1 m.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2f2e8909-7c99-5473-92c5-0ca6ff491806', 'c0c1987c-1721-5f72-9c37-822234cac0a9', '69f49b38-4492-521c-be78-56effb528ad2', 'ib', 'A.1', 'IB A.1 Kinematics', 5, 5, 'What does the gradient of a displacement–time graph represent?', 1, 'multiple_choice'::answer_type, 'Velocity', NULL, NULL, false, 'Gradient = change in displacement ÷ change in time = velocity. A curved displacement–time graph therefore means the velocity is changing.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fac8a579-e48b-55d7-9466-c18f74447af1', '2f2e8909-7c99-5473-92c5-0ca6ff491806', 'Velocity', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e62b479f-0546-5b06-b443-f7c143f9a5e0', '2f2e8909-7c99-5473-92c5-0ca6ff491806', 'Acceleration', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6ac51855-1a9b-5e0b-bafa-544ec4130021', '2f2e8909-7c99-5473-92c5-0ca6ff491806', 'Distance travelled', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('10b81c8e-4c4d-5d78-8c3d-3eb468c65a48', '2f2e8909-7c99-5473-92c5-0ca6ff491806', 'Displacement', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
